__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"readingSamples",{enumerable:!0,get:function(){return t}});const t=[{id:'a-better-meeting',title:'\u4e00\u5c01\u66f4\u6e05\u695a\u7684\u6703\u8b70\u9080\u8acb',tag:'\u5de5\u4f5c\u6e9d\u901a',minutes:2,body:'Hi Alex,\n\nCould we move our meeting to Friday? I need a little more time to review the plan. Please share your notes before the meeting so that everyone can prepare.\n\nOur goal is simple: choose one idea that we can test next week. We do not need a perfect answer today. We need a clear next step.\n\nThank you for your help. I look forward to hearing your thoughts.'},{id:'a-small-weekend',title:'\u628a\u9031\u672b\u7559\u7d66\u4e00\u9ede\u597d\u5947',tag:'\u65e5\u5e38\u95b1\u8b80',minutes:2,body:'On Saturday, Maya decided to take a different way home. She found a small book shop near the river bank. The owner was kind and offered her a cup of water.\n\nMaya was curious about a book on the table. It told the story of a family who chose to run a quiet cafe in the mountains.\n\nShe bought the book and sat by the window. For the first time that week, she was in no hurry. Sometimes a small change can make an ordinary day feel special.'},{id:'a-flight-change',title:'\u51fa\u767c\u524d\uff0c\u5148\u628a\u554f\u984c\u554f\u6e05\u695a',tag:'\u65c5\u884c\u5be6\u7528',minutes:2,body:'Our plane will take off two hours later than planned. We have enough time to get some food, but we should stay near the gate.\n\nI asked the staff a simple question: "Will we still arrive before the last train leaves?" She checked the schedule and helped us find another way to the hotel.\n\nTravel does not always go as expected. A clear question and a little patience can help us find a solution.'}]},274,[]);
